"""Activate service port for C-plane tracing on vCU via OAMCU."""

import logging
import json
from taf.internal.managedobject import ManagedObject, Using

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class VcuServicePortSetter(
        Using("vcu_connection"),
        ManagedObject):
    """
    Activate the service port for C-plane tracing on vCU via OAMCU.
    """

    TIMEOUT = 60

    def _activate_service_port(self):
        """
        Activates the service port on the vCU.
        """
        delta = [{'distName': "MRBTS-1/MNL-1/MNLENT-1/SECADM-1",
                  'operation': "create",
                  'parameters': [{'parameterName': 'actServicePortState',
                                  'value': 'true',
                                  'operation': 'create'}]}]

        commissionoing_result = self.vcu_connection.perform_delta_recommissioning(delta_file=json.dumps(delta))

        assert commissionoing_result['status'] == 'success', "Failing in activating Service Port for VCU"

    def _setup(self):
        self._activate_service_port()
